72	    /** Add a period, refused when its name is in use on the sheet, its to-date is before its
73	     *  from-date, or it shares a day with another of the sheet's periods. The cap, when given, is how many
74	     *  OPEN or PENDING claims a person may have in it; null for none. */
75	    @Transactional
76	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
77	        sheets.load(sheetId);
78	        // Periods of a sheet are added one at a time, so two added at once cannot overlap.
79	        sheetRows.findForUpdate(sheetId);
80	        if (to.isBefore(from)) {
81	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
82	        }
83	        if (periods.existsBySheetIdAndNameKey(sheetId, Period.keyOf(name))) {
84	            throw nameInUse();
85	        }
86	        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
87	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period overlaps another period.");
88	        }
89	        Period saved;
90	        try {
91	            saved = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
92	        } catch (DataIntegrityViolationException raced) {
93	            throw nameInUse();
94	        }
95	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
96	                + " from=" + saved.getFrom() + " to=" + saved.getTo()
97	                + (saved.getCap() == null ? "" : " cap=" + saved.getCap()));
98	        return saved;
99	    }
