101	    /** Generate one period per calendar month from the from-date's month to the to-date's month, each
102	     *  from the first to the last day of its month and named yyyy-mm; a blank date is the sheet's today.
103	     *  A month whose name is in use on the sheet, or whose days overlap one of its periods, is left out.
104	     *  Refused when the to-date is before the from-date. The periods made, in date order; a viewer makes none. */
105	    @Transactional
106	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
107	        sheets.load(sheetId);
108	        if (settings.roleOf(sheetId, user) == Role.VIEWER) return List.of();
109	        sheetRows.findForUpdate(sheetId);
110	        LocalDate today = sheets.today(sheetId);
111	        LocalDate start = from == null ? today : from;
112	        LocalDate end = to == null ? today : to;
113	        if (end.isBefore(start)) {
114	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
115	        }
116	        return generateMonths(sheetId, user, YearMonth.from(start), YearMonth.from(end));
117	    }
118	
119	    /** Generate the twelve monthly periods of a fiscal year, as {@link #generate} does from the first day of
120	     *  the year to its last: the year named FY&lt;year&gt; starts on the first day of the sheet's fiscal start
121	     *  month in that calendar year. The periods made, in date order. */
122	    @Transactional
123	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
124	        sheets.load(sheetId);
125	        sheetRows.findForUpdate(sheetId);
126	        YearMonth first = YearMonth.of(year, settings.fiscalStartMonth(sheetId));
127	        return generateMonths(sheetId, user, first, first.plusMonths(11));
128	    }
129	
130	    /** Generate the four calendar quarters of a year, named &lt;yyyy&gt;-Q1 to &lt;yyyy&gt;-Q4, each as the
131	     *  period form would add it; a quarter whose name is in use on the sheet, or whose days overlap one of
132	     *  its periods, is left out. The periods made, in date order. */
133	    @Transactional
134	    public List<Period> generateQuarters(String sheetId, String user, int year) {
135	        sheets.load(sheetId);
136	        sheetRows.findForUpdate(sheetId);
137	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
138	        List<Period> made = new ArrayList<>();
139	        for (int quarter = 1; quarter <= 4; quarter++) {
140	            YearMonth firstMonth = YearMonth.of(year, quarter * 3 - 2);
141	            makeUnlessTaken(sheetId, user, existing, made, year + "-Q" + quarter,
142	                    firstMonth.atDay(1), firstMonth.plusMonths(2).atEndOfMonth());
143	        }
144	        return made;
145	    }
146	
147	    /** Make one period per month from the first month to the last, leaving out those whose name is in use
148	     *  or whose days overlap a period; the periods made, in date order. */
149	    private List<Period> generateMonths(String sheetId, String user, YearMonth firstMonth, YearMonth lastMonth) {
150	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
151	        List<Period> made = new ArrayList<>();
152	        for (YearMonth month = firstMonth; !month.isAfter(lastMonth); month = month.plusMonths(1)) {
153	            makeUnlessTaken(sheetId, user, existing, made, month.toString(), month.atDay(1), month.atEndOfMonth());
154	        }
155	        return made;
156	    }
157	
158	    /** Make a generated period unless its name is in use or its days overlap one of the existing periods,
159	     *  adding it to both the existing and the made periods. */
160	    private void makeUnlessTaken(String sheetId, String user, List<Period> existing, List<Period> made,
161	            String name, LocalDate first, LocalDate last) {
162	        if (existing.stream().anyMatch(p -> p.getNameKey().equals(Period.keyOf(name)) || p.overlaps(first, last))) {
163	            return;
164	        }
165	        Period saved = periods.saveAndFlush(new Period(sheetId, name, first, last));
166	        existing.add(saved);
167	        made.add(saved);
168	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
169	                + " from=" + saved.getFrom() + " to=" + saved.getTo());
170	    }
