172	    /** Close a period, fixing at this moment its due-total and each person's due-total for it: the figures as shown now of the claims
173	     *  due by a date in it that were open or settled at the end of its last day (by their status logs), skipping those that are n/a and the unbound open claims of a person whose retirement date is reached, and the claims deferred on the sheet's today; and each person's carried figure for it: the figures as shown now of their claims counted so that belong to a period ending before it starts and were still open (PENDING included) at its end, with their opening balance for it. A soft-closed period is closed with its figures fixed afresh. Refused when the period is already closed, or the sheet's permission matrix does not allow the user's role to close. */
174	    @Transactional
175	    public Period close(String sheetId, String user, long id) {
176	        // Locked as claim changes lock it, so no claim in the period changes while it is closed.
177	        sheetRows.findForUpdate(sheetId);
178	        Period period = periods.findByIdAndSheetId(id, sheetId)
179	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
180	        settings.refuseUnlessPermitted(sheetId, user, "close", "Your role may not close a period on this sheet.");
181	        if (period.isClosed()) {
182	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
183	        }
184	        return closeNow(sheetId, user, period, false, false);
185	    }
186	
187	    /** Soft-close a period: its due-total and each person's due-total for it are fixed at this moment as
188	     *  a close fixes them, while claims dated in it can still be added and changed. Refused when the
189	     *  period is closed or soft-closed already, or the sheet's permission matrix does not allow the
190	     *  user's role to close. */
191	    @Transactional
192	    public Period softClose(String sheetId, String user, long id) {
193	        sheetRows.findForUpdate(sheetId);
194	        Period period = periods.findByIdAndSheetId(id, sheetId)
195	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
196	        settings.refuseUnlessPermitted(sheetId, user, "close", "Your role may not close a period on this sheet.");
197	        if (period.isClosed() || period.isSoftClosed()) {
198	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
199	        }
200	        return closeNow(sheetId, user, period, false, true);
201	    }
