203	    /** Once the sheet's today is changed, close each open period whose to-date plus the sheet's grace days
204	     *  is before the new today (a soft-closed period keeps the figures fixed when it was soft-closed), in order of their to-dates, as a close by hand would; none when the grace
205	     *  days are blank. Each is audited as closed automatically. */
206	    @EventListener
207	    @Transactional
208	    public void closeOverdue(TodayChanged change) {
209	        Integer grace = settings.graceDays(change.sheetId());
210	        if (grace == null) return;
211	        sheetRows.findForUpdate(change.sheetId());
212	        List<Period> due = periods.findBySheetIdOrderByFromAsc(change.sheetId()).stream()
213	                .filter((p) -> !p.isClosed() && !p.isSoftClosed() && p.getTo().plusDays(grace).isBefore(change.today()))
214	                .sorted(Comparator.comparing(Period::getTo)).toList();
215	        for (Period period : due) closeNow(change.sheetId(), change.user(), period, true, false);
216	    }
