218	    /** Close (or soft-close) a period now, fixing its figures; the audit line marks a close the today change made. */
219	    private Period closeNow(String sheetId, String user, Period period, boolean auto, boolean soft) {
220	        Map<Long, Person> peopleById = people.findInListOrder(sheetId).stream()
221	                .collect(Collectors.toMap(Person::getId, Function.identity()));
222	        LocalDate today = sheets.today(sheetId);
223	        BigDecimal total = BigDecimal.ZERO.setScale(2);
224	        Map<Long, BigDecimal> personTotals = new HashMap<>();
225	        Map<Long, BigDecimal> personCarried = new HashMap<>();
226	        for (Long personId : peopleById.keySet()) {
227	            personTotals.put(personId, BigDecimal.ZERO.setScale(2));
228	            personCarried.put(personId, period.openingOf(personId));
229	        }
230	        List<Period> all = periods.findBySheetIdOrderByFromAsc(sheetId);
231	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
232	            Person person = peopleById.get(claim.getPersonId());
233	            if (person == null) continue;
234	            // Counted by the status the claim had at the end of the period's last day; a reached retirement
235	            // only leaves out a claim still open now, as it touches only live claims. A hold leaves none out.
236	            ClaimStatus then = claim.statusAsOf(period.getTo());
237	            if (!counts(claim, person, then, today)) continue;
238	            // Carried: still open at the end of this period, belonging to a period ending before it starts.
239	            boolean carried = then.isOpen() && all.stream()
240	                    .anyMatch((p) -> p.contains(claim.getDueBy()) && p.getTo().isBefore(period.getFrom()));
241	            if (!carried && !period.contains(claim.getDueBy())) continue;
242	            BigDecimal due = claimService.due(sheetId, person, claim);
243	            if (due == null) continue;
244	            if (carried) {
245	                personCarried.merge(person.getId(), due, BigDecimal::add);
246	            } else {
247	                total = total.add(due);
248	                personTotals.merge(person.getId(), due, BigDecimal::add);
249	            }
250	        }
251	        if (soft) period.softClose(total, personTotals, personCarried);
252	        else period.close(total, personTotals, personCarried);
253	        // Every pool member's cut for the period is fixed as it stands now, the sheet's today as it is.
254	        period.fixPoolCuts(PoolCuts.of(pools.findBySheetIdOrderByIdAsc(sheetId),
255	                crews.findBySheetIdOrderByIdAsc(sheetId), people.findInListOrder(sheetId), settings.pot(sheetId), today));
256	        Period saved = periods.saveAndFlush(period);
257	        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
258	                + " total=" + total.toPlainString() + (auto ? " auto=yes" : ""));
259	        return saved;
260	    }
261	
262	    /** Whether a claim counts toward a period's figures, by the status it had at the end of the period's
263	     *  last day: open or settled then, not deferred on the sheet's today, and, when unbound and open still,
264	     *  its person's retirement date not reached. */
265	    private static boolean counts(Claim claim, Person person, ClaimStatus then, LocalDate today) {
266	        return then != null && !claim.isDeferredOn(today) && (then == ClaimStatus.SETTLED
267	                || (then.isOpen() && (claim.isStated() || !claim.getStatus().isOpen() || !person.isRetiredBy(today))));
268	    }
