270	    /** Roll a fiscal year over: generate the next fiscal year's twelve monthly periods as
271	     *  {@link #generateFiscalYear} does, then add to each person's opening balance for the new year's first
272	     *  period their open figure at the end of the old year's last period: the due of their claims that
273	     *  count, belonging to a period of the old year, and OPEN or PENDING at that period's end; none when the
274	     *  year has been rolled over already and that rollover is not undone. Then every period of the old year
275	     *  still open is soft-closed, in start-date order, as a soft close would. Refused unless
276	     *  the user acts as a steward, and when the old year has no periods. The periods made, in date order. */
277	    @Transactional
278	    public List<Period> rollover(String sheetId, String user, int year) {
279	        sheets.load(sheetId);
280	        sheetRows.findForUpdate(sheetId);
281	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
282	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may roll the year over.");
283	        }
284	        YearMonth first = YearMonth.of(year, settings.fiscalStartMonth(sheetId));
285	        LocalDate oldFrom = first.atDay(1);
286	        LocalDate oldTo = first.plusMonths(11).atEndOfMonth();
287	        List<Period> oldYear = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
288	                .filter((p) -> !p.getFrom().isBefore(oldFrom) && !p.getTo().isAfter(oldTo)).toList();
289	        if (oldYear.isEmpty()) {
290	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The fiscal year FY" + year + " has no periods.");
291	        }
292	        Period last = oldYear.stream().max(Comparator.comparing(Period::getTo)).orElseThrow();
293	        LocalDate today = sheets.today(sheetId);
294	        List<Person> listed = people.findInListOrder(sheetId);
295	        Map<Long, Person> peopleById = listed.stream().collect(Collectors.toMap(Person::getId, Function.identity()));
296	        Map<Long, BigDecimal> open = new HashMap<>();
297	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
298	            Person person = peopleById.get(claim.getPersonId());
299	            if (person == null) continue;
300	            ClaimStatus then = claim.statusAsOf(last.getTo());
301	            if (!counts(claim, person, then, today) || !then.isOpen()) continue;
302	            if (oldYear.stream().noneMatch((p) -> p.contains(claim.getDueBy()))) continue;
303	            BigDecimal due = claimService.due(sheetId, person, claim);
304	            if (due != null) open.merge(person.getId(), due, BigDecimal::add);
305	        }
306	
307	        List<Period> made = generateMonths(sheetId, user, first.plusMonths(12), first.plusMonths(23));
308	        Rollover rollover = new Rollover(sheetId, year, user, today);
309	        made.forEach((p) -> rollover.getPeriodIds().add(p.getId()));
310	        LocalDate newFrom = first.plusMonths(12).atDay(1);
311	        LocalDate newTo = first.plusMonths(23).atEndOfMonth();
312	        Period opening = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
313	                .filter((p) -> !p.getFrom().isBefore(newFrom) && !p.getTo().isAfter(newTo)).findFirst().orElse(null);
314	        // A year rolled over already, and not undone, has carried its open figures; they are not carried twice.
315	        boolean carried = rollovers.existsBySheetIdAndYearAndUndoneFalse(sheetId, year);
316	        if (opening != null && !carried) {
317	            for (Person person : listed) {
318	                BigDecimal amount = open.get(person.getId());
319	                if (amount == null || amount.signum() == 0) continue;
320	                opening.addOpening(person.getId(), amount);
321	                rollover.getOpenings().merge(person.getId(), amount.setScale(2), BigDecimal::add);
322	                audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user + " name=" + person.getName()
323	                        + " period=" + opening.getName() + " amount=" + amount.setScale(2).toPlainString());
324	            }
325	            periods.saveAndFlush(opening);
326	            rollover.setOpeningPeriodId(opening.getId());
327	        }
328	        rollovers.saveAndFlush(rollover);
329	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user + " fy=FY" + year + " periods=" + made.size());
330	        // Every period of the old year still open is soft-closed, in start-date order, as a soft close would.
331	        for (Period period : oldYear) {
332	            if (!period.isClosed() && !period.isSoftClosed()) closeNow(sheetId, user, period, false, true);
333	        }
334	        return made;
335	    }
336	
337	    /** Undo the sheet's last rollover: remove the periods it generated and take back the opening balances it
338	     *  added. Refused unless the user made it, and on the sheet's today it was made on; when it is undone
339	     *  already, there is none, or a claim belongs to (is due by a date in) a period it generated. */
340	    @Transactional
341	    public void undoRollover(String sheetId, String user) {
342	        sheets.load(sheetId);
343	        sheetRows.findForUpdate(sheetId);
344	        Rollover rollover = rollovers.findFirstBySheetIdOrderByIdDesc(sheetId).filter((r) -> !r.isUndone())
345	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no rollover to undo."));
346	        if (!rollover.getMadeBy().equals(user) || settings.roleOf(sheetId, user) != Role.STEWARD) {
347	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who rolled the year over may undo it.");
348	        }
349	        if (!rollover.getMadeOn().equals(sheets.today(sheetId))) {
350	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A rollover can be undone only on the day it was made.");
351	        }
352	        List<Period> generated = periods.findAllById(rollover.getPeriodIds());
353	        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
354	        if (all.stream().anyMatch((c) -> generated.stream().anyMatch((p) -> p.contains(c.getDueBy())))) {
355	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A claim belongs to a period the rollover generated.");
356	        }
357	        if (rollover.getOpeningPeriodId() != null && !rollover.getPeriodIds().contains(rollover.getOpeningPeriodId())) {
358	            periods.findByIdAndSheetId(rollover.getOpeningPeriodId(), sheetId).ifPresent((opening) -> {
359	                rollover.getOpenings().forEach(opening::takeBackOpening);
360	                periods.saveAndFlush(opening);
361	            });
362	        }
363	        periods.deleteAll(generated);
364	        rollover.undo();
365	        rollovers.saveAndFlush(rollover);
366	        audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user + " fy=FY" + rollover.getYear());
367	    }
368	
369	    /** Reopen a closed or soft-closed period, making its due-total and its pool members' cuts live again. Refused when the sheet's permission
370	     *  matrix does not allow the user's role to reopen (by default, only a steward), or the period is not closed. */
371	    @Transactional
372	    public Period reopen(String sheetId, String user, long id) {
373	        // Locked as closing locks it, so a reopen and a close of the period do not cross.
374	        sheetRows.findForUpdate(sheetId);
375	        Period period = periods.findByIdAndSheetId(id, sheetId)
376	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
377	        settings.refuseUnlessPermitted(sheetId, user, "reopen", "Your role may not reopen a period on this sheet.");
378	        if (period.isLocked()) {
379	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is locked.");
380	        }
381	        if (!period.isClosed() && !period.isSoftClosed()) {
382	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed.");
383	        }
384	        period.reopen();
385	        Period saved = periods.saveAndFlush(period);
386	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
387	        return saved;
388	    }
389	
390	    /** Lock or unlock a period; a locked period cannot be reopened. Refused unless the user acts as a
391	     *  steward, and when the period is already locked (or, to unlock, not locked). */
392	    @Transactional
393	    public Period setLocked(String sheetId, String user, long id, boolean locked) {
394	        sheetRows.findForUpdate(sheetId);
395	        Period period = periods.findByIdAndSheetId(id, sheetId)
396	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period."));
397	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
398	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may lock or unlock a period.");
399	        }
400	        if (period.isLocked() == locked) {
401	            throw new ResponseStatusException(HttpStatus.CONFLICT,
402	                    locked ? "The period is already locked." : "The period is not locked.");
403	        }
404	        period.setLocked(locked);
405	        Period saved = periods.saveAndFlush(period);
406	        audit.recordOnCommit((locked ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
407	                + " period=" + saved.getName());
408	        return saved;
409	    }
