package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /** What the screen shows of a period: its name and its from and to dates, both inclusive, whether
     *  it is closed, whether it is soft-closed and, once closed or soft-closed, the due-total fixed then (null while open) and each person's
     *  due-total and carried figure fixed then, by person id (empty while open), its cap on each person's open claims (null for none),
     *  each person's opening balance for it, by person id (a person missing has none), whether it is locked, and
     *  each pool member's cut fixed when it was closed or soft-closed, by member key, by pool id (a crew's
     *  negated; a pool that showed no cuts then is missing; empty while open). */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedTotal, Map<Long, String> closedPersonTotals, Integer cap,
            Map<Long, String> closedPersonCarried, Map<Long, String> personOpenings, boolean locked,
            Map<Long, Map<String, String>> closedPoolCuts) {
        static PeriodView of(Period period) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getClosedPersonTotals().forEach((id, total) -> personTotals.put(id, total.toPlainString()));
            Map<Long, String> personCarried = new TreeMap<>();
            period.getClosedPersonCarried().forEach((id, carried) -> personCarried.put(id, carried.toPlainString()));
            Map<Long, String> openings = new TreeMap<>();
            period.getPersonOpenings().forEach((id, amount) -> openings.put(id, amount.toPlainString()));
            Map<Long, Map<String, String>> poolCuts = new TreeMap<>();
            period.getClosedPoolCuts().forEach((poolId, cuts) -> {
                Map<String, String> shown = new TreeMap<>();
                cuts.forEach((key, cut) -> shown.put(key, cut.setScale(2).toPlainString()));
                poolCuts.put(poolId, shown);
            });
            return new PeriodView(period.getId(), period.getName(), period.getFrom(), period.getTo(),
                    period.isClosed(), period.isSoftClosed(),
                    period.getClosedTotal() == null ? null : period.getClosedTotal().toPlainString(),
                    personTotals, period.getCap(), personCarried, openings, period.isLocked(), poolCuts);
        }
    }

    /** A period's fields, as entered on the form; a blank cap is none. */
    public record PeriodForm(@NotBlank @Size(max = 200) String name, @NotNull LocalDate from,
            @NotNull LocalDate to, @Min(1) Integer cap) {
    }

    /** The dates monthly periods are generated between; a blank date is the sheet's today. */
    public record GenerateForm(LocalDate from, LocalDate to) {
    }

    /** The calendar year a fiscal year starts in, as entered. */
    public record GenerateFiscalYearForm(@NotNull @Min(1) @Max(9998) Integer year) {
    }

    /** The calendar year the fiscal year rolled over starts in, as entered. */
    public record RolloverForm(@NotNull @Min(1) @Max(9997) Integer year) {
    }

    /** What a rollover did: how many periods it made, and the sheet's periods now. */
    public record RolloverView(int made, List<PeriodView> periods) {
    }

    /** The calendar year whose quarters are generated, as entered. */
    public record GenerateQuartersForm(@NotNull @Min(1) @Max(9999) Integer year) {
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    /** The sheet's periods in date order. */
    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(PeriodView::of).toList();
    }

    /** Add a period to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid PeriodForm form) {
        return PeriodView.of(service.add(sheetId.trim(), SignedInUser.name(user), form.name(), form.from(),
                form.to(), form.cap()));
    }

    /** Generate one period per calendar month from the from-date's month to the to-date's month,
     *  leaving out those whose name is in use or whose days overlap a period; the periods made. */
    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody GenerateForm form) {
        return service.generate(sheetId.trim(), SignedInUser.name(user), form.from(), form.to()).stream()
                .map(PeriodView::of).toList();
    }

    /** Generate the twelve monthly periods of a fiscal year, as the monthly generator does; the periods made. */
    @PostMapping("/generate-fy")
    public List<PeriodView> generateFiscalYear(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid GenerateFiscalYearForm form) {
        return service.generateFiscalYear(sheetId.trim(), SignedInUser.name(user), form.year()).stream()
                .map(PeriodView::of).toList();
    }

    /** Roll a fiscal year over into the next, carrying each person's open figure into its first period;
     *  a steward only. */
    @PostMapping("/rollover")
    public RolloverView rollover(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid RolloverForm form) {
        String sheet = sheetId.trim();
        int made = service.rollover(sheet, SignedInUser.name(user), form.year()).size();
        return new RolloverView(made, service.list(sheet).stream().map(PeriodView::of).toList());
    }

    /** Undo the sheet's last rollover, on the day it was made, by the steward who made it; the sheet's periods now. */
    @PostMapping("/rollover/undo")
    public List<PeriodView> undoRollover(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = sheetId.trim();
        service.undoRollover(sheet, SignedInUser.name(user));
        return service.list(sheet).stream().map(PeriodView::of).toList();
    }

    /** Generate the four calendar quarters of a year, leaving out those whose name is in use or whose days
     *  overlap a period; the periods made. */
    @PostMapping("/generate-quarters")
    public List<PeriodView> generateQuarters(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid GenerateQuartersForm form) {
        return service.generateQuarters(sheetId.trim(), SignedInUser.name(user), form.year()).stream()
                .map(PeriodView::of).toList();
    }

    /** Close a period, fixing its due-total. */
    @PostMapping("/{id}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.close(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Soft-close a period, fixing its figures while its claims can still change. */
    @PostMapping("/{id}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.softClose(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Reopen a closed or soft-closed period, making its due-total live again; a steward only. */
    @PostMapping("/{id}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.reopen(sheetId.trim(), SignedInUser.name(user), id));
    }

    /** Lock a period, so it cannot be reopened; a steward only. */
    @PostMapping("/{id}/lock")
    public PeriodView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.setLocked(sheetId.trim(), SignedInUser.name(user), id, true));
    }

    /** Unlock a locked period; a steward only. */
    @PostMapping("/{id}/unlock")
    public PeriodView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        return PeriodView.of(service.setLocked(sheetId.trim(), SignedInUser.name(user), id, false));
    }
}
package net.officefloor.hq.app.claim;

/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim can be VOID, and a steward
 *  may void a SETTLED one within 7 days of its settlement.
 *  A clerk's settling above the clerk limit leaves an OPEN claim PENDING, which a steward approves
 *  (SETTLED) or rejects (OPEN again); a PENDING claim is otherwise handled as an OPEN one.
 *  A DRAFT can be DELETED, which counts nowhere, and restored (a DRAFT again) on the day it was deleted.
 *  A DRAFT whose due is above the sheet's review threshold goes to REVIEW when opened: it counts nowhere and
 *  has no number until a steward's review makes it OPEN; it can be voided. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** Whether a claim in this status may move to `next` by opening, settling or voiding it; only a
     *  steward's approval or rejection moves a PENDING claim on. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN, REVIEW -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == REVIEW || isOpen();
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
        };
    }
}
